// Builds the entries of a configs table with one head dim and dtype, and
// registers their launch functions. Each (kernel, head dim, dtype) is a
// translation unit generated by cmake/rocm_rdna_singleseq_attn.cmake, so the
// builds compile in parallel.
#pragma once

#include <iterator>
#include <utility>

#include "rdna_singleseq_decode_attn.cu"
#include "rdna_singleseq_prefill_attn.cu"

namespace rdna_singleseq {

template <HeadDim kHeadDim, Dtype kDtype, size_t... I>
bool register_decode(std::index_sequence<I...>) {
  (
      [] {
        constexpr DecodeConfig c = kDecodeConfigs[I];
        if constexpr (c.head_dim == kHeadDim && c.dtype == kDtype)
          decode_launchers()[I] = &launch_decode<c>;
      }(),
      ...);
  return true;
}

template <HeadDim kHeadDim, Dtype kDtype>
bool register_decode() {
  return register_decode<kHeadDim, kDtype>(
      std::make_index_sequence<std::size(kDecodeConfigs)>{});
}

template <HeadDim kHeadDim, Dtype kDtype, size_t... I>
bool register_decode_batch(std::index_sequence<I...>) {
  (
      [] {
        constexpr DecodeConfig c = kDecodeBatchConfigs[I];
        if constexpr (c.head_dim == kHeadDim && c.dtype == kDtype)
          decode_batch_launchers()[I] = &launch_decode<c, true>;
      }(),
      ...);
  return true;
}

template <HeadDim kHeadDim, Dtype kDtype>
bool register_decode_batch() {
  return register_decode_batch<kHeadDim, kDtype>(
      std::make_index_sequence<std::size(kDecodeBatchConfigs)>{});
}

template <HeadDim kHeadDim, Dtype kDtype, size_t... I>
bool register_prefill(std::index_sequence<I...>) {
  (
      [] {
        constexpr PrefillConfig c = kPrefillConfigs[I];
        if constexpr (c.head_dim == kHeadDim && c.dtype == kDtype)
          prefill_launchers()[I] = &launch_prefill<c>;
      }(),
      ...);
  return true;
}

template <HeadDim kHeadDim, Dtype kDtype>
bool register_prefill() {
  return register_prefill<kHeadDim, kDtype>(
      std::make_index_sequence<std::size(kPrefillConfigs)>{});
}

}  // namespace rdna_singleseq
